import type Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";

const MODEL = "claude-opus-4-5";
const MAX_TOKENS = 16384;
// Task mode: the agent is here to get the user's work done. Learning mode is
// the secondary mode we layer on top of a transcript this produces, so this
// prompt must not pre-emptively tutor - the whole premise of the prototype is
// that a user watching a capable agent work becomes a passive observer.
const SYSTEM = [
  "You are a capable engineering assistant helping the user complete a task.",
  "Work the problem directly: make concrete decisions, write real code, and",
  "state your reasoning as you go rather than asking the user to supply it.",
  "Be concise. Do not quiz the user, do not pad explanations for a beginner,",
  "and do not check whether they are following - just do the work well.",
].join(" ");

export type Message = { role: "user" | "assistant"; text: string };

/** The subset of WebSocket the conversation uses, so tests can stand in for it. */
export type Socket = {
  send(data: string): void;
  addEventListener(
    type: "message",
    listener: (e: MessageEvent<string>) => void,
  ): void;
};

export class Conversation {
  private readonly turns: Anthropic.MessageParam[];
  private pending: { requestId: string; blocks: string[] } | undefined;
  private settle: (() => void) | undefined;
  onChange: (() => void) | undefined;

  private readonly socket: Socket;
  private readonly system: string;
  /** Turn 0 when present: sent like any other turn, never rendered. */
  readonly seed: string | undefined;

  constructor(
    socket: Socket,
    opts: {
      system?: string;
      initialTurns?: Anthropic.MessageParam[];
      seed?: string;
    } = {},
  ) {
    this.socket = socket;
    this.system = opts.system ?? SYSTEM;
    this.seed = opts.seed;
    this.turns = opts.seed
      ? [{ role: "user", content: opts.seed }]
      : [...(opts.initialTurns ?? [])];
    socket.addEventListener("message", (e: MessageEvent<string>) => {
      this.handleFrame(JSON.parse(e.data) as ServerFrame);
    });
  }

  /** Committed turns plus the one currently streaming. */
  get messages(): ReadonlyArray<Message> {
    const turns = this.seed ? this.turns.slice(1) : this.turns;
    const committed = turns.map(
      (turn): Message => ({
        role: turn.role === "assistant" ? "assistant" : "user",
        text: textOf(turn),
      }),
    );
    const streaming = this.pending?.blocks.join("");
    if (streaming) committed.push({ role: "assistant", text: streaming });
    return committed;
  }

  get inFlight(): boolean {
    return this.pending !== undefined;
  }

  send(text: string): Promise<void> {
    if (this.pending) return Promise.resolve();
    this.turns.push({ role: "user", content: text });
    return this.request();
  }

  /** Requests a reply to the turns already present - the seeded first turn of
   * a learning thread, which the user never typed. */
  start(): Promise<void> {
    if (this.pending || this.turns.length === 0) return Promise.resolve();
    return this.request();
  }

  private request(): Promise<void> {
    const requestId = crypto.randomUUID();
    this.pending = { requestId, blocks: [] };
    const message: ClientMessage = {
      type: "start",
      requestId,
      params: {
        model: MODEL,
        max_tokens: MAX_TOKENS,
        system: this.system,
        stream: true,
        messages: [...this.turns],
      },
    };
    this.socket.send(JSON.stringify(message));
    this.onChange?.();
    return new Promise<void>((resolve) => {
      this.settle = resolve;
    });
  }

  handleFrame(frame: ServerFrame): void {
    const pending = this.pending;
    if (!pending || frame.requestId !== pending.requestId) return;
    switch (frame.type) {
      case "event":
        this.handleEvent(frame.event);
        break;
      case "done":
      case "error":
        // A turn that ends without a message_stop still commits whatever text
        // arrived, so the next turn's array stays valid.
        this.commit();
        break;
    }
    this.onChange?.();
  }

  private handleEvent(event: Anthropic.RawMessageStreamEvent): void {
    const pending = this.pending;
    if (!pending) return;
    // RawMessageStreamEvent is an open union we forward verbatim from the SDK,
    // so an unrecognized event warns rather than throwing - a version bump
    // should not break a stream we can otherwise render.
    switch (event.type) {
      case "content_block_start":
        pending.blocks[event.index] = blockStartText(event.content_block);
        break;
      case "content_block_delta":
        pending.blocks[event.index] =
          (pending.blocks[event.index] ?? "") + deltaText(event.delta);
        break;
      case "message_stop":
        this.commit();
        break;
      case "message_start":
      case "message_delta":
      case "content_block_stop":
        break;
      default:
        console.warn("unhandled stream event", event);
    }
  }

  private commit(): void {
    const pending = this.pending;
    if (!pending) return;
    this.pending = undefined;
    const text = pending.blocks.join("");
    // MessageParam content must be non-empty, so an empty response is dropped.
    if (text.length > 0) this.turns.push({ role: "assistant", content: text });
    this.settle?.();
    this.settle = undefined;
  }
}

function textOf(turn: Anthropic.MessageParam): string {
  if (typeof turn.content === "string") return turn.content;
  return turn.content
    .map((block) => (block.type === "text" ? block.text : ""))
    .join("");
}

/** This prototype has no tools and no thinking, so the non-text variants are
 * listed to be explicitly ignored rather than silently dropped - when we add
 * them, this is where they surface. */
function blockStartText(block: Anthropic.ContentBlock): string {
  switch (block.type) {
    case "text":
      return block.text;
    default:
      console.warn("unhandled content block", block);
      return "";
  }
}

function deltaText(delta: Anthropic.RawContentBlockDelta): string {
  switch (delta.type) {
    case "text_delta":
      return delta.text;
    default:
      console.warn("unhandled content block delta", delta);
      return "";
  }
}

import type Anthropic from "@anthropic-ai/sdk";

export type ClientMessage = {
  type: "start";
  requestId: string;
  params: Anthropic.MessageCreateParamsStreaming;
};

export type ServerFrame =
  | { type: "event"; requestId: string; event: Anthropic.RawMessageStreamEvent }
  | { type: "done"; requestId: string }
  | { type: "error"; requestId: string; message: string };

import { Conversation, type Socket } from "./conversation.ts";
import { type Action, LEARNING_SYSTEM, seedTurn } from "./prompt.ts";
import type { Anchor, Mark, ThreadId } from "./selection.ts";

export type { Action };

/** `anchor.thread` is the parent, so the link upward is the highlight itself. */
export type Origin = { anchor: Anchor; action: Action };

export type Thread = {
  id: ThreadId;
  /** null only for the root task thread. */
  origin: Origin | null;
  conversation: Conversation;
  /** Creation order; each child's `origin.anchor` is its highlight. */
  children: ThreadId[];
  activeChild: ThreadId | null;
  draft: string;
};

/** The tree of conversations. Every thread but the root was opened from a
 * passage of its parent, so a thread and the highlight over its parent are the
 * same edge seen from either end. Threads are never destroyed or reparented. */
export class ThreadTree {
  private readonly threads = new Map<ThreadId, Thread>();
  private nextId = 0;
  readonly root: ThreadId;
  private readonly socket: Socket;
  /** Attached to every conversation the tree owns, so a stream anywhere in the
   * tree re-syncs the app. */
  private readonly onChange: () => void;

  constructor(socket: Socket, root: Conversation, onChange: () => void) {
    this.socket = socket;
    this.onChange = onChange;
    this.root = this.add(null, root);
  }

  get(id: ThreadId): Thread {
    const thread = this.threads.get(id);
    if (!thread) throw new Error(`unknown thread ${id}`);
    return thread;
  }

  /** Seeds a child conversation from the parent's own seed plus its transcript
   * up to `anchor`, links it in, and makes it the parent's active child. The
   * caller starts it: the tree does not own the request lifecycle. */
  open(anchor: Anchor, action: Action): ThreadId {
    const parent = this.get(anchor.thread);
    const conversation = new Conversation(this.socket, {
      system: LEARNING_SYSTEM,
      seed: seedTurn(
        parent.conversation.seed,
        parent.conversation.messages,
        anchor,
        action,
      ),
    });
    const id = this.add({ anchor, action }, conversation);
    parent.children.push(id);
    parent.activeChild = id;
    return id;
  }

  /** The highlights to draw over `id`'s transcript: one per child. */
  marks(id: ThreadId): Mark[] {
    return this.get(id).children.map((child) => {
      const origin = this.get(child).origin;
      if (!origin) throw new Error("child thread without an origin");
      return { thread: child, anchor: origin.anchor };
    });
  }

  /** root -> id, for the depth indicator. */
  path(id: ThreadId): ThreadId[] {
    const out: ThreadId[] = [];
    let at: ThreadId | undefined = id;
    while (at) {
      out.unshift(at);
      at = this.get(at).origin?.anchor.thread;
    }
    return out;
  }

  private add(origin: Origin | null, conversation: Conversation): ThreadId {
    const id = `t${this.nextId++}` as ThreadId;
    conversation.onChange = this.onChange;
    this.threads.set(id, {
      id,
      origin,
      conversation,
      children: [],
      activeChild: null,
      draft: "",
    });
    return id;
  }
}

import type { JSONSchemaType } from "openai/lib/jsonschema.mjs";
import {
  PLACEHOLDER_NATIVE_MESSAGE_IDX,
  type ProviderToolSpec,
} from "../providers/provider-types.ts";
import type {
  ExecutingToolInvocation,
  GenericToolRequest,
  ToolName,
} from "../tool-types.ts";
import type { Result } from "../utils/result.ts";

export type Input = {
  result?: string;
  [key: string]: unknown;
};

/** The call's input, thread-side. The thread builds the `YieldValue` from it;
 * the model never sees it. */
export type StructuredResult = { toolName: "yield_to_parent"; input: Input };

export type ToolRequest = GenericToolRequest<"yield_to_parent", Input>;

export function execute(request: ToolRequest): ExecutingToolInvocation {
  return {
    promise: Promise.resolve({
      type: "tool_result" as const,
      id: request.id,
      result: {
        status: "ok" as const,
        value: [
          {
            type: "text" as const,
            // The model just wrote the yielded text; echoing it back only
            // spends tokens.
            text: "Yield acknowledged.",
            nativeMessageIdx: PLACEHOLDER_NATIVE_MESSAGE_IDX,
          },
        ],
        structuredResult: {
          toolName: "yield_to_parent" as const,
          input: request.input,
        },
      },
      nativeMessageIdx: PLACEHOLDER_NATIVE_MESSAGE_IDX,
    }),
    abort: () => {},
  };
}

const DEFAULT_INPUT_SCHEMA: JSONSchemaType = {
  type: "object",
  properties: {
    result: {
      type: "string",
      description: "The result or information to return to the parent agent",
    },
  },
  required: ["result"],
};

export function getSpec(yieldSchema?: JSONSchemaType): ProviderToolSpec {
  return {
    ...spec,
    input_schema: yieldSchema ?? DEFAULT_INPUT_SCHEMA,
  };
}

export const spec: ProviderToolSpec = {
  name: "yield_to_parent" as ToolName,
  description: `\
Yield results to the parent agent.

CRITICAL: You MUST use this tool when your task is complete, or the parent agent will never receive your results.

Make sure you address every part of the original prompt you were given.
The parent agent can only observe your final yield message - none of the rest of the text is visible to the parent.
After using this tool, the sub-agent thread will be terminated.`,
  input_schema: {
    type: "object",
    properties: {
      result: {
        type: "string",
        description: "The result or information to return to the parent agent",
      },
    },
    required: ["result"],
  },
};

export function validateInput(input: {
  [key: string]: unknown;
}): Result<Input> {
  if ("result" in input && typeof input.result !== "string") {
    return {
      status: "error",
      error: `expected req.input.result to be a string but it was ${JSON.stringify(input.result)}`,
    };
  }

  return {
    status: "ok",
    value: input as Input,
  };
}

import { Conversation } from "../conversation.ts";
import { actionLabel } from "../prompt.ts";
import { selectedSample } from "../samples/index.ts";
import { anchorText, overlaps, type ThreadId } from "../selection.ts";
import { ThreadTree } from "../threads.ts";
import { AppView, type Msg, type State } from "../view.ts";

function connect(): WebSocket {
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  return new WebSocket(`${proto}//${window.location.host}/api/socket`);
}

/** Prototype 1: the task transcript, with learning threads hanging off the
 * passages the user picks out of it. */
export function mount(container: HTMLElement): void {
  // One socket for the whole app: every thread's Conversation adds its own
  // listener and drops frames whose requestId it does not own, so streams
  // interleave over the single connection.
  const socket = connect();
  const tree = new ThreadTree(
    socket,
    new Conversation(socket, { initialTurns: selectedSample()?.turns }),
    () => {
      refresh();
      view.sync(state);
    },
  );
  // The thread on the left. Moved only by the arrows.
  let focus = tree.root;

  const state: State = {
    messages: [],
    inFlight: false,
    draft: "",
    split: false,
    depth: 0,
    canDescend: false,
    thread: focus,
    marks: [],
    activeMark: null,
    anchor: null,
    query: "",
    origin: null,
    child: null,
  };

  /** Re-projects the tree onto the view's state. Everything but the fields the
   * user is editing is derived, so this runs after every dispatch. */
  function refresh(): void {
    const thread = tree.get(focus);
    state.thread = focus;
    state.depth = state.split ? tree.path(focus).length : 0;
    state.canDescend = thread.activeChild !== null;
    state.messages = thread.conversation.messages;
    state.inFlight = thread.conversation.inFlight;
    state.draft = thread.draft;
    state.marks = tree.marks(focus);
    const own = thread.origin;
    state.origin = own
      ? {
          action: actionLabel(own.action),
          quote: anchorText(
            own.anchor,
            tree.get(own.anchor.thread).conversation.messages,
          ),
        }
      : null;
    state.activeMark = thread.activeChild;
    const activeChild = thread.activeChild;
    if (!activeChild) {
      state.child = null;
      return;
    }
    const child = tree.get(activeChild);
    const origin = child.origin;
    state.child = {
      action: origin ? actionLabel(origin.action) : "",
      messages: child.conversation.messages,
      inFlight: child.conversation.inFlight,
      draft: child.draft,
    };
  }

  function send(id: ThreadId): void {
    const thread = tree.get(id);
    const text = thread.draft.trim();
    if (text === "" || thread.conversation.inFlight) return;
    thread.draft = "";
    thread.conversation.send(text).then(undefined, (e: unknown) => {
      console.error(e);
    });
  }

  function update(state: State, msg: Msg): void {
    const thread = tree.get(focus);
    switch (msg.type) {
      case "DRAFT_CHANGED":
        thread.draft = msg.draft;
        break;
      case "SUBMIT":
        send(focus);
        break;
      case "GO_DEEPER": {
        if (!state.split) {
          state.split = true;
          break;
        }
        const child = thread.activeChild;
        if (!child) break;
        focus = child;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "GO_BACK": {
        const parent = thread.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        state.anchor = null;
        state.query = "";
        break;
      }
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        thread.activeChild = null;
        break;
      case "MARK_CLICKED":
        state.anchor = null;
        thread.activeChild = msg.thread;
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(state.marks, anchor)) break;
            const id = tree.open(anchor, msg.msg.action);
            state.anchor = null;
            state.query = "";
            tree
              .get(id)
              .conversation.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = thread.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
        }
        break;
      }
    }
    refresh();
  }

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    dispatching = false;
  }

  refresh();
  const view = new AppView(container, dispatch, state);
}

import Anthropic from "@anthropic-ai/sdk";
import type { ClientMessage, ServerFrame } from "@edulab/iso/protocol.ts";
import websocket from "@fastify/websocket";
import type { FastifyInstance } from "fastify";

export async function registerSocket(app: FastifyInstance, apiKey: string) {
  const client = new Anthropic({ apiKey });
  await app.register(websocket);

  app.get("/api/socket", { websocket: true }, (socket) => {
    const send = (frame: ServerFrame) => {
      if (socket.readyState === socket.OPEN) socket.send(JSON.stringify(frame));
    };

    socket.on("message", (data: Buffer) => {
      let message: ClientMessage;
      try {
        message = JSON.parse(data.toString()) as ClientMessage;
      } catch {
        socket.close(4400, "bad_request");
        return;
      }
      void run(message);
    });

    // The server is a pipe: it forwards every event to the client tagged with
    // the request id, and always terminates the request with done | error.
    async function run(message: ClientMessage) {
      const { requestId } = message;
      try {
        const stream = client.messages.stream(message.params);
        for await (const event of stream) {
          send({ type: "event", requestId, event });
        }
        send({ type: "done", requestId });
      } catch (err) {
        send({
          type: "error",
          requestId,
          message: err instanceof Error ? err.message : String(err),
        });
      }
    }
  });
}

